    for (String node : nodes) hash.addNode(node, 5);
    Map<Object, String> data = new LinkedHashMap<>();
    data.put("", n1);
    data.put("asdf", n3);
    data.put("224ea4cd-f449-4dcb-869a-5317c63bd619", n2);
