    getTypedValue("org.apache.ignite.lang.IgniteUuid", ik2.toString(), iv2.toString());
    // Test tuple.
    IgniteCache<Integer, T2<Integer, String>> cTuple = typedCache();
    T2<Integer, String> tup = new T2<>(1, "test");
