    getTypedValue("int", "555", JSON_MAPPER.writeValueAsString(tup));
    // Test enum.
    IgniteCache<Integer, CacheMode> cEnum = typedCache();
    cEnum.put(888, PARTITIONED);
    getTypedValue("int", "888", PARTITIONED.toString());
