    int i = 1;
    for (BaselineNode n : grid(0).cluster().nodes()) {
        params.add("consistentId" + i++);
        params.add(String.valueOf(n.consistentId()));
    }
    assertBaseline(content(null, GridRestCommand.BASELINE_SET, params.toArray(new String[0])), sz + 1, sz + 1);
    stopGrid(sz);
}

