 */
@Test
public void testJoin() throws Exception {
    ResultSet rs = stmt.executeQuery("select p.id, p.name, o.name as orgName from \"pers\".Person p, \"org\".Organization o where p.orgId = o.id");
    assert rs != null;
    int cnt = 0;
    while (rs.next()) {
        int id = rs.getInt("id");
        if (id == 1) {
            assert "John White".equals(rs.getString("name"));
            assert "A".equals(rs.getString("orgName"));
        } else if (id == 2) {
            assert "Joe Black".equals(rs.getString("name"));
            assert "A".equals(rs.getString("orgName"));
        } else if (id == 3) {
            assert "Mike Green".equals(rs.getString("name"));
            assert "B".equals(rs.getString("orgName"));
        } else
            assert false : "Wrong ID: " + id;
        cnt++;
    }
    assert cnt == 3;
}

