            assertTrue("Expected update count of an empty statement.", p.getUpdateCount() != -1);
            assertTrue("More results are expected.", p.getMoreResults());
            assertTrue("Expected update count of the BEGIN", p.getUpdateCount() != -1);
            assertTrue("More results are expected.", p.getMoreResults());
