            stmt.close();
            TestSQLFunctions.reqLatch.countDown();
        } catch (Exception e) {
            log.error("Unexpected exception.", e);
            fail("Unexpected exception");
        }
    });
    GridTestUtils.assertThrows(log, () -> {
        stmt.executeQuery("select * from Integer where _key in " + "(select _key from Integer where awaitLatchCancelled() = 0) and shouldNotBeCalledInCaseOfCancellation()");
