/**
 * Test that client works properly with servers txId intersection.
 */
@Test
@SuppressWarnings("ThrowableNotThrown")
public void testTxWithIdIntersection() throws Exception {
    int CLUSTER_SIZE = 2;
    try (LocalIgniteCluster cluster = LocalIgniteCluster.start(CLUSTER_SIZE);
        IgniteClient client = Ignition.startClient(new ClientConfiguration().setAddresses(cluster.clientAddresses().toArray(new String[CLUSTER_SIZE])))) {
        ClientCache<Integer, Integer> cache = client.createCache(new ClientCacheConfiguration().setName("cache").setAtomicityMode(CacheAtomicityMode.TRANSACTIONAL));
        CyclicBarrier barrier = new CyclicBarrier(2);
        GridTestUtils.runAsync(() -> {
            try {
                // Another thread starts transaction here.
                barrier.await(1, TimeUnit.SECONDS);
                for (int i = 0; i < CLUSTER_SIZE; i++) dropAllThinClientConnections(Ignition.allGrids().get(i));
                ClientTransaction tx = client.transactions().txStart();
                barrier.await(1, TimeUnit.SECONDS);
                // Another thread puts to cache here.
                barrier.await(1, TimeUnit.SECONDS);
                tx.commit();
                barrier.await(1, TimeUnit.SECONDS);
            } catch (Exception e) {
                log.error("Unexpected error", e);
            }
        });
        ClientTransaction tx = client.transactions().txStart();
        barrier.await(1, TimeUnit.SECONDS);
        // Another thread drops connections and create new transaction here, which started on another node with the
        // same transaction id as we started in this thread.
        barrier.await(1, TimeUnit.SECONDS);
        GridTestUtils.assertThrows(null, () -> {
            cache.put(0, 0);
            return null;
        }, ClientException.class, "Transaction context has been lost due to connection errors");
        tx.close();
        barrier.await(1, TimeUnit.SECONDS);
        // Another thread commit transaction here.
        barrier.await(1, TimeUnit.SECONDS);
        assertFalse(cache.containsKey(0));
    }
}

/**
 * Test reconnection throttling.
 */
@Test
@SuppressWarnings("ThrowableNotThrown")
public void testReconnectionThrottling() throws Exception {
    int throttlingRetries = 5;
    long throttlingPeriod = 3_000L;
    try (LocalIgniteCluster cluster = LocalIgniteCluster.start(1);
        IgniteClient client = Ignition.startClient(new ClientConfiguration().setReconnectThrottlingPeriod(throttlingPeriod).setReconnectThrottlingRetries(throttlingRetries).setAddresses(cluster.clientAddresses().toArray(new String[1])))) {
        ClientCache<Integer, Integer> cache = client.createCache("cache");
        for (int i = 0; i < throttlingRetries; i++) {
            // Attempts to reconnect within throttlingRetries should pass.
            cache.put(0, 0);
            dropAllThinClientConnections(Ignition.allGrids().get(0));
            GridTestUtils.assertThrowsWithCause(() -> cache.put(0, 0), ClientConnectionException.class);
        }
        for (// Attempts to reconnect after throttlingRetries should fail.
        int i = 0; // Attempts to reconnect after throttlingRetries should fail.
        i < 10; // Attempts to reconnect after throttlingRetries should fail.
        i++) GridTestUtils.assertThrowsWithCause(() -> cache.put(0, 0), ClientConnectionException.class);
        doSleep(throttlingPeriod);
        // Attempt to reconnect after throttlingPeriod should pass.
        assertTrue(GridTestUtils.waitForCondition(() -> {
            try {
                cache.put(0, 0);
                return true;
            } catch (ClientConnectionException e) {
                return false;
            }
        }, throttlingPeriod));
    }
}

