    typeIdField.set(timeBinField, decimalValBinObj.typeId());
    String expMsg = exceptionMessageOfDifferentTypeIdBinaryField(decimalValBinObj.typeId(), decimalVal.getClass().getName(), timeValBinObj.typeId(), timeVal.getClass().getName(), U.field(timeBinField, "fieldId"), timeBinField.name(), null);
    assertThrows(log, () -> timeBinField.value(timeValBinObj), BinaryObjectException.class, expMsg);
}

