                    throw new IllegalStateException(e);
                } finally {
                    int cnt0 = cnt.incrementAndGet();
                    if (cnt0 % 100 == 0)
                        info("Tasks finished: " + cnt0);
                }
            }
            info("Thread " + Thread.currentThread().getId() + " finishing.");
