 */
@Test
public void testFailedClientLeavesTopologyAfterTimeout() throws Exception {
    IgniteEx srv0 = startGrid(0);
    IgniteEx client00 = startClientGrid("client00");
    Thread.sleep(5_000);
    client00.getOrCreateCache(new CacheConfiguration<>("cache0"));
