            CompositeData c1 = conns.get(new Object[] { 1 });
            if (c0.get("type").equals("JDBC")) {
                checkJdbc.accept(c0);
                checkThin.accept(c1);
            } else {
                checkJdbc.accept(c1);
                checkThin.accept(c0);
            }
            assertEquals(2, conns.size());
        }
    }
