                    while (!stop.get()) {
                        try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
                            for (int i = 0; i < KEYS; i++) {
                                if (rnd.nextBoolean())
                                    cache.get(i);
                            }
                        }
                    }
                }
            }, 3, "tx-thread");
            IgniteInternalFuture<?> changeTopFut = null;
            if (changeTop) {
                changeTopFut = GridTestUtils.runAsync(new Callable<Void>() {

                    @Override
                    public Void call() throws Exception {
                        while (!stop.get()) {
                            startGrid(NODES);
                            stopGrid(NODES);
                        }
                        return null;
                    }
                });
            }
            U.sleep(rnd.nextInt(500));
            fut.cancel();
            U.sleep(rnd.nextInt(500));
            stop.set(true);
            try {
                fut.get();
            } catch (Exception e) {
                info("Ignore error: " + e);
            }
            if (changeTopFut != null)
                changeTopFut.get();
            info("Try get");
            try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
                for (int k = 0; k < KEYS; k++) cache.get(k);
            }
            info("Try get done");
            startGrid(NODES);
            stopGrid(NODES);
        } finally {
            stop.set(true);
        }
    }
}

