/**
 * {@inheritDoc}
 */
@SuppressWarnings("BusyWait")
@Test
@Override
public void testLockUnlock() throws Exception {
    if (lockingEnabled()) {
        final CountDownLatch lockCnt = new CountDownLatch(1);
        final CountDownLatch unlockCnt = new CountDownLatch(1);
        grid(0).events().localListen(new IgnitePredicate<Event>() {

            @Override
            public boolean apply(Event evt) {
                switch(evt.type()) {
                    case EVT_CACHE_OBJECT_LOCKED:
                        lockCnt.countDown();
                        break;
                    case EVT_CACHE_OBJECT_UNLOCKED:
                        unlockCnt.countDown();
                        break;
                }
                return true;
            }
        }, EVT_CACHE_OBJECT_LOCKED, EVT_CACHE_OBJECT_UNLOCKED);
        IgniteCache<String, Integer> nearCache = jcache();
        IgniteCache<String, Integer> cache = fullCache();
        String key = primaryKeysForCache(cache, 1).get(0);
        nearCache.put(key, 1);
        assert !nearCache.isLocalLocked(key, false);
        assert !cache.isLocalLocked(key, false);
        Lock lock = nearCache.lock(key);
        lock.lock();
        try {
            lockCnt.await();
            assert nearCache.isLocalLocked(key, false);
            assert cache.isLocalLocked(key, false);
        } finally {
            lock.unlock();
        }
        unlockCnt.await();
        for (int i = 0; i < 100; i++) {
            if (cache.isLocalLocked(key, false))
                Thread.sleep(10);
            else
                break;
        }
        assert !nearCache.isLocalLocked(key, false);
        assert !cache.isLocalLocked(key, false);
    }
}

