        Lock lock1_2 = cache.lockAll(ImmutableSet.of("key1", "key2"));
        lock1_2.lock();
        try {
            assert cache.isLocalLocked("key1", false);
            assert cache.isLocalLocked("key2", false);
        } finally {
            lock1_2.unlock();
        }
        for (int i = 0; i < 100; i++) if (cache.isLocalLocked("key1", false) || cache.isLocalLocked("key2", false))
            Thread.sleep(10);
        else
            break;
        assert !cache.isLocalLocked("key1", false);
        assert !cache.isLocalLocked("key2", false);
        lock1_2.lock();
        try {
            assert cache.isLocalLocked("key1", false);
            assert cache.isLocalLocked("key2", false);
        } finally {
            lock1_2.unlock();
        }
        for (int i = 0; i < 100; i++) if (cache.isLocalLocked("key1", false) || cache.isLocalLocked("key2", false))
            Thread.sleep(10);
        else
            break;
        assert !cache.isLocalLocked("key1", false);
        assert !cache.isLocalLocked("key2", false);
    }
}

