                    isOk.set(!cache.lockAll(Arrays.asList(keys.get(0), keys.get(1))).tryLock(5000, MILLISECONDS));
                } catch (InterruptedException ignored) {
                    isOk.set(false);
                }
            }
        });
        t.start();
