                info("Terminal ID: " + terminalId);
                terminalsPerSrvr++;
                if (terminalsPerSrvr == srvrMaxNoTerminals)
                    break;
            }
        }
        displayReqCount();
        ExecutorService pool = Executors.newFixedThreadPool(clients.size());
        pool.invokeAll(clients);
        Thread.sleep(Long.MAX_VALUE);
    } finally {
        stopAllGrids();
    }
}

