 */
@Test
public void testWrite() throws Exception {
    final AtomicInteger putCnt = new AtomicInteger();
    final AtomicInteger rmvCnt = new AtomicInteger();
    store = new CacheStoreAdapter<Object, Object>() {

        @Override
        public Object load(Object key) {
            info(">>> Get [key=" + key + ']');
            return null;
        }

        @Override
        public void write(javax.cache.Cache.Entry<? extends Object, ? extends Object> entry) {
            putCnt.incrementAndGet();
        }

        @Override
        public void delete(Object key) {
            rmvCnt.incrementAndGet();
        }
    };
    startGrid();
    IgniteCache<Integer, String> cache = jcache();
    try {
        cache.get(1);
        Transaction tx = grid().transactions().txStart();
        try {
            for (int i = 1; i <= 10; i++) cache.put(i, Integer.toString(i));
            tx.commit();
        } finally {
            tx.close();
        }
        assert cache.size() == 10;
        assert putCnt.get() == 10;
        tx = grid().transactions().txStart();
        try {
            for (int i = 1; i <= 10; i++) {
                String val = cache.getAndRemove(i);
                assert val != null;
                assert val.equals(Integer.toString(i));
            }
            tx.commit();
        } finally {
            tx.close();
        }
        assert rmvCnt.get() == 10;
    } finally {
        stopGrid();
    }
}

/**
 * @throws Exception If failed.
 */
@Test
public void testEvictions() throws Exception {
    try {
        MvccFeatureChecker.skipIfNotSupported(MvccFeatureChecker.Feature.EVICTION);
        final Ignite ignite1 = startGrid(1);
        final IgniteCache<Integer, Object> cache1 = ignite1.cache(DEFAULT_CACHE_NAME);
        for (int i = 0; i < 5000; i++) cache1.put(i, VALUE + i);
        info("Finished data population.");
        final AtomicBoolean done = new AtomicBoolean();
        final CountDownLatch startLatch = new CountDownLatch(1);
        int oldSize = cache1.localSize(CachePeekMode.ALL);
        IgniteInternalFuture fut = multithreadedAsync(new Callable<Object>() {

            @Nullable
            @Override
            public Object call() throws Exception {
                startLatch.await();
                info("Started evicting...");
                for (int i = 0; i < 3000 && !done.get(); i++) {
                    Cache.Entry<Integer, Object> entry = cache1.getEntry(i);
                    if (entry != null)
                        ignite1.cache(DEFAULT_CACHE_NAME).localEvict(Collections.<Object>singleton(entry.getKey()));
                    else
                        info("Entry is null.");
                }
                info("Finished evicting.");
                return null;
            }
        }, 1);
        ignite1.events().localListen(new IgnitePredicate<Event>() {

            @Override
            public boolean apply(Event evt) {
                startLatch.countDown();
                return true;
            }
        }, EVT_NODE_JOINED);
        final Ignite ignite2 = startGrid(2);
        done.set(true);
        fut.get();
        sleepUntilCashesEqualize(ignite1, ignite2, oldSize);
        checkCachesConsistency(ignite1, ignite2);
        oldSize = cache1.size(CachePeekMode.ALL);
        info("Evicting on constant topology.");
        for (int i = 0; i < 1000; i++) {
            Cache.Entry<Integer, Object> entry = randomEntry(ignite1);
            if (entry != null)
                cache1.localEvict(Collections.singleton(entry.getKey()));
            else
                info("Entry is null.");
        }
        sleepUntilCashesEqualize(ignite1, ignite2, oldSize);
        checkCachesConsistency(ignite1, ignite2);
    } finally {
        stopAllGrids();
    }
}

