/**
 * @throws Exception In case of error.
 */
@Test
public void testSize() throws Exception {
    assert jcache().localSize() == 0;
    int size = 10;
    final Map<String, Integer> map = new HashMap<>();
    for (int i = 0; i < size; i++) map.put("key" + i, i);
    // Put in primary nodes to avoid near readers which will prevent entry from being cleared.
    Map<ClusterNode, Collection<String>> mapped = grid(0).<String>affinity(cacheName()).mapKeysToNodes(map.keySet());
    for (int i = 0; i < gridCount(); i++) {
        Collection<String> keys = mapped.get(grid(i).localNode());
        if (!F.isEmpty(keys)) {
            for (String key : keys) jcache(i).put(key, map.get(key));
        }
    }
    map.remove("key0");
    mapped = grid(0).<String>affinity(cacheName()).mapKeysToNodes(map.keySet());
    for (int i = 0; i < gridCount(); i++) {
        // Will actually delete entry from map.
        CU.invalidate(jcache(i), "key0");
        assertNull("Failed check for grid: " + i, jcache(i).localPeek("key0", ONHEAP));
        Collection<String> keysCol = mapped.get(grid(i).localNode());
        assert jcache(i).localSize() != 0 || F.isEmpty(keysCol);
    }
    for (int i = 0; i < gridCount(); i++) executeOnLocalOrRemoteJvm(i, new CheckCacheSizeTask(map, cacheName()));
    for (int i = 0; i < gridCount(); i++) {
        Collection<String> keysCol = mapped.get(grid(i).localNode());
        assertEquals("Failed check for grid: " + i, !F.isEmpty(keysCol) ? keysCol.size() : 0, jcache(i).localSize(PRIMARY));
    }
    int globalPrimarySize = map.size();
    for (int i = 0; i < gridCount(); i++) assertEquals(globalPrimarySize, jcache(i).size(PRIMARY));
    for (int i = 0; i < gridCount(); i++) assertEquals(globalPrimarySize, jcache(i).sizeLong(PRIMARY));
    for (int i = 0; i < gridCount(); i++) assertEquals(globalPrimarySize, (int) jcache(i).sizeAsync(PRIMARY).get());
    for (int i = 0; i < gridCount(); i++) assertEquals((long) globalPrimarySize, (long) jcache(i).sizeLongAsync(PRIMARY).get());
    for (int i = 0; i < gridCount(); i++) {
        IgniteCacheProxy cache = (IgniteCacheProxy) jcache(i);
        long cacheSize = 0;
        int parts = cache.context().affinity().partitions();
        for (int part = 0; part < parts; ++part) cacheSize += jcache(i).sizeLong(part, PRIMARY);
        assertEquals((long) globalPrimarySize, cacheSize);
    }
    for (int i = 0; i < gridCount(); i++) {
        IgniteCacheProxy cache = (IgniteCacheProxy) jcache(i);
        long cacheSize = 0;
        int parts = cache.context().affinity().partitions();
        for (int part = 0; part < parts; ++part) cacheSize += jcache(i).sizeLongAsync(part, PRIMARY).get();
        assertEquals((long) globalPrimarySize, cacheSize);
    }
    int times = 1;
    if (cacheMode() == REPLICATED)
        times = gridCount() - clientsCount();
    else if (cacheMode() == PARTITIONED)
        times = Math.min(gridCount(), jcache().getConfiguration(CacheConfiguration.class).getBackups() + 1);
    int globalSize = globalPrimarySize * times;
    for (int i = 0; i < gridCount(); i++) assertEquals(globalSize, jcache(i).size(ALL));
}

