@Test
public void testInvokeAllAppliedOnceOnBinaryTypeRegistration() {
    IgniteCache<MyKey, Integer> cache = jcache();
    Affinity<Object> affinity = grid(0).affinity(cache.getName());
    for (int i = 0; i < gridCount(); i++) {
        if (!affinity.isPrimary(grid(i).localNode(), new MyKey(""))) {
            cache = jcache(i);
            break;
        }
    }
    LinkedHashSet<MyKey> keys = new LinkedHashSet<>(Arrays.asList(new MyKey("remove_0"), new MyKey("1"), new MyKey("2"), new MyKey("remove_3"), new MyKey("remove_4"), new MyKey("register_type_0"), new MyKey("6"), new MyKey("remove_7"), new MyKey("register_type_1"), new MyKey("9"), new MyKey("remove_10"), new MyKey("11"), new MyKey("12"), new MyKey("register_type_2")));
    for (MyKey key : keys) cache.put(key, 0);
    cache.invokeAll(keys, new CacheEntryProcessor<MyKey, Integer, Object>() {

        @IgniteInstanceResource
        Ignite ignite;

        @Override
        public Object process(MutableEntry<MyKey, Integer> entry, Object... objects) throws EntryProcessorException {
            String key = entry.getKey().key;
            if (key.startsWith("register_type")) {
                BinaryObjectBuilder bo = ignite.binary().builder(key);
                bo.build();
            }
            if (key.startsWith("remove")) {
                entry.remove();
            } else {
                Integer value = entry.getValue() == null ? 0 : entry.getValue();
                entry.setValue(++value);
            }
            if (key.startsWith("register_type"))
                return results[Integer.parseInt(key.substring(key.lastIndexOf("_") + 1))];
            return null;
        }
    });
    Map<MyKey, Integer> all = cache.getAll(keys);
    for (Map.Entry<MyKey, Integer> entry : all.entrySet()) {
        MyKey key = entry.getKey();
        if (key.key.startsWith("remove")) {
            assertNull(entry.getValue());
            if (cacheStoreFactory() != null)
                assertNull(storeMap.get(keys));
        } else {
            int value = entry.getValue();
            assertEquals("\"" + key + "' entry has wrong value, exp=1 actl=" + value, 1, value);
            if (cacheStoreFactory() != null)
                assertEquals("\"" + key + "' entry has wrong value in cache store, exp=1 actl=" + value, 1, (int) storeMap.get(key));
        }
    }
}

