/**
 * @throws IgniteCheckedException If failed.
 */
@Test
public void testSize() throws Exception {
    Ignite node = startGrid(0);
    IgniteCache cache = node.createCache(cacheConfiguration(PARTITIONED, FULL_SYNC, 0, 1));
    assertEquals(cache.size(), 0);
    final int KEYS = 10;
    // Initial put.
    for (int i = 0; i < KEYS; i++) {
        final Integer key = i;
        try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
            cache.put(key, i);
            tx.commit();
        }
        assertEquals(i + 1, cache.size());
    }
    // Update.
    for (int i = 0; i < KEYS; i++) {
        final Integer key = i;
        try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
            cache.put(key, i);
            tx.commit();
        }
        assertEquals(KEYS, cache.size());
    }
    int size = KEYS;
    // Remove.
    for (int i = 0; i < KEYS; i++) {
        if (i % 2 == 0) {
            final Integer key = i;
            try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
                cache.remove(key);
                tx.commit();
            }
            size--;
            assertEquals(size, cache.size());
        }
    }
    // Check size does not change if remove already removed keys.
    for (int i = 0; i < KEYS; i++) {
        if (i % 2 == 0) {
            final Integer key = i;
            try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
                cache.remove(key);
                tx.commit();
            }
            assertEquals(size, cache.size());
        }
    }
    // Check rollback create.
    for (int i = 0; i < KEYS; i++) {
        if (i % 2 == 0) {
            final Integer key = i;
            try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
                cache.put(key, i);
                tx.rollback();
            }
            assertEquals(size, cache.size());
        }
    }
    // Check rollback update.
    for (int i = 0; i < KEYS; i++) {
        final Integer key = i;
        try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
            cache.put(key, -1);
            tx.rollback();
        }
        assertEquals(size, cache.size());
    }
    // Check rollback create.
    for (int i = 0; i < KEYS; i++) {
        if (i % 2 == 0) {
            final Integer key = i;
            try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
                cache.put(key, i);
                tx.rollback();
            }
            assertEquals(size, cache.size());
        }
    }
    // Check rollback update.
    for (int i = 0; i < KEYS; i++) {
        final Integer key = i;
        try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
            cache.put(key, -1);
            tx.rollback();
        }
        assertEquals(size, cache.size());
    }
    // Check rollback remove.
    for (int i = 0; i < KEYS; i++) {
        final Integer key = i;
        try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
            cache.remove(key);
            tx.rollback();
        }
        assertEquals(size, cache.size());
    }
    // Restore original state.
    for (int i = 0; i < KEYS; i++) {
        if (i % 2 == 0) {
            final Integer key = i;
            try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
                cache.put(key, i);
                tx.commit();
            }
            size++;
            assertEquals(size, cache.size());
        }
    }
    // Check state.
    for (int i = 0; i < KEYS; i++) assertEquals(i, cache.get(i));
}

