 */
@Test
public void testLostRollbackOnBackup() throws Exception {
    IgniteEx node = startGrid(0);
    startGrid(1);
    node.cluster().active(true);
    final CyclicBarrier barrier = new CyclicBarrier(2);
    GridTestUtils.runAsync(new Runnable() {

        @Override
        public void run() {
            try {
                barrier.await();
                stopGrid(1);
                barrier.await();
                startGrid(1);
                barrier.await();
            } catch (Exception e) {
                barrier.reset();
            }
        }
    });
    IgniteCache<Integer, Integer> cache = node.getOrCreateCache(DEFAULT_CACHE_NAME);
    Integer key = primaryKey(cache);
    cache.put(key, 0);
    IgniteTransactions txs = node.transactions();
    try (Transaction tx = txs.txStart(TransactionConcurrency.PESSIMISTIC, TransactionIsolation.REPEATABLE_READ)) {
        assertEquals((Integer) 0, cache.get(key));
        cache.put(key, 1);
        barrier.await();
        // Await backup node stop.
        barrier.await();
        Thread.sleep(1000);
        tx.rollback();
    }
    barrier.await();
    assertEquals((Integer) 0, cache.get(key));
    cache.put(key, 2);
    assertEquals((Integer) 2, cache.get(key));
}

