/**
 * @throws Exception When fails.
 */
@Test
public void test() throws Exception {
    Ignite ex = startGrid(0);
    ex.active(true);
    startGrid(1);
    final CountDownLatch startLatch = new CountDownLatch(1);
    final CountDownLatch doneLatch = new CountDownLatch(1);
    final Ignite ex1 = ex;
    final AtomicBoolean stop = new AtomicBoolean();
    final AtomicInteger keyCnt = new AtomicInteger();
    Thread thread = new Thread(new Runnable() {

        @Override
        public void run() {
            ex1.active(true);
            try {
                checkTopology(2);
                startLatch.countDown();
                IgniteCache<Object, Object> cache1 = ex1.cache(DEFAULT_CACHE_NAME);
                int key = keyCnt.get();
                while (!stop.get()) {
                    if (key > 0 && (key % 500 == 0)) {
                        U.sleep(5);
                        System.out.println("key = " + key);
                    }
                    cache1.put(key, -key);
                    key = keyCnt.incrementAndGet();
                }
            } catch (Throwable th) {
                th.printStackTrace();
            }
            doneLatch.countDown();
        }
    });
    thread.setName("Data-Loader");
    thread.start();
    startLatch.await(60, TimeUnit.SECONDS);
    for (int i = 2; i < CLUSTER_SIZE; i++) {
        startGrid(i);
        U.sleep(SF.apply(3000));
    }
    U.sleep(SF.apply(5000));
    IgniteProcessProxy.kill("db.RebalancingOnNotStableTopologyTest2");
    Thread.sleep(SF.apply(3000));
    IgniteProcessProxy.kill("db.RebalancingOnNotStableTopologyTest1");
    assert doneLatch.getCount() > 0;
    stop.set(true);
    doneLatch.await(600, TimeUnit.SECONDS);
    IgniteProcessProxy.killAll();
    stopAllGrids();
    //start cluster. it will cause memory restoration and reading WAL.
    ex = startGrids(CLUSTER_SIZE);
    ex.active(true);
    checkTopology(CLUSTER_SIZE);
    IgniteCache<Object, Object> cache1 = ex.cache(DEFAULT_CACHE_NAME);
    assert keyCnt.get() > 0;
    for (int i = 0; i < keyCnt.get(); i++) assertEquals(-i, cache1.get(i));
    System.out.println("Test finished with total keys count = " + keyCnt.get());
}

/**
 * Tests that range reserved method return correct number of reserved WAL segments.
 *
 * @throws Exception if failed.
 */
@Test
public void testWalManagerRangeReservation() throws Exception {
    IgniteEx ig0 = prepareGrid(4);
    GridCacheDatabaseSharedManager dbMgr = (GridCacheDatabaseSharedManager) ig0.context().cache().context().database();
    IgniteWriteAheadLogManager wal = ig0.context().cache().context().wal();
    long resIdx = getReservedWalSegmentIndex(dbMgr);
    assertTrue("Expected that at least resIdx greater than 0, real is " + resIdx, resIdx > 0);
    FileWALPointer lowPtr = (FileWALPointer) dbMgr.checkpointHistory().firstCheckpointPointer();
    assertTrue("Expected that dbMbr returns valid resIdx", lowPtr.index() == resIdx);
    // Reserve previous WAL segment.
    wal.reserve(new FileWALPointer(resIdx - 1, 0, 0));
    int resCnt = wal.reserved(new FileWALPointer(resIdx - 1, 0, 0), new FileWALPointer(resIdx, 0, 0));
    assertTrue("Expected resCnt is 2, real is " + resCnt, resCnt == 2);
}

/**
 * Tests that grid cache manager correctly truncates unused WAL segments;
 *
 * @throws Exception if failed.
 */
@Test
public void testWalDoesNotTruncatedWhenSegmentReserved() throws Exception {
    IgniteEx ig0 = prepareGrid(4);
    GridCacheDatabaseSharedManager dbMgr = (GridCacheDatabaseSharedManager) ig0.context().cache().context().database();
    IgniteWriteAheadLogManager wal = ig0.context().cache().context().wal();
    long resIdx = getReservedWalSegmentIndex(dbMgr);
    assertTrue("Expected that at least resIdx greater than 0, real is " + resIdx, resIdx > 0);
    FileWALPointer lowPtr = (FileWALPointer) dbMgr.checkpointHistory().firstCheckpointPointer();
    assertTrue("Expected that dbMbr returns valid resIdx", lowPtr.index() == resIdx);
    // Reserve previous WAL segment.
    wal.reserve(new FileWALPointer(resIdx - 1, 0, 0));
    int numDel = wal.truncate(null, lowPtr);
    int expNumDel = (int) resIdx - 1;
    assertTrue("Expected del segments is " + expNumDel + ", real is " + numDel, expNumDel == numDel);
}

