/**
 * Checks that we reserve and release the same WAL index on exchange.
 */
@Test
public void testReservation() throws Exception {
    IgniteEx ig = startGrid(0);
    ig.cluster().baselineAutoAdjustEnabled(false);
    ig.cluster().active(true);
    ig.getOrCreateCache(new CacheConfiguration<>(SLOW_REBALANCE_CACHE).setAtomicityMode(CacheAtomicityMode.TRANSACTIONAL).setAffinity(new RendezvousAffinityFunction(false, 1)).setBackups(1).setWriteSynchronizationMode(CacheWriteSynchronizationMode.FULL_SYNC).setRebalanceBatchSize(100));
    try (IgniteDataStreamer<Object, Object> streamer = ig.dataStreamer(SLOW_REBALANCE_CACHE)) {
        for (int i = 0; i < 3_000; i++) streamer.addData(i, new byte[5 * 1000]);
        streamer.flush();
    }
    startGrid(1);
    resetBaselineTopology();
    IgniteCache<Object, Object> anotherCache = ig.getOrCreateCache(new CacheConfiguration<>(REGULAR_CACHE).setAtomicityMode(CacheAtomicityMode.TRANSACTIONAL).setAffinity(new RendezvousAffinityFunction(false, 1)).setBackups(1).setWriteSynchronizationMode(CacheWriteSynchronizationMode.FULL_SYNC).setRebalanceBatchSize(100));
    // To let distributedExchange() finish.
    Thread.sleep(7_000);
    for (int i = 0; i < WAL_HISTORY_SIZE; i++) {
        for (int j = 0; i < 500; i++) anotherCache.put(j, new byte[5 * 1000]);
        // Checkpoints where partition is OWNING on grid(0), MOVING on grid(1)
        forceCheckpoint();
        for (int j = 0; i < 500; i++) anotherCache.put(j, new byte[5 * 1000]);
    }
    SUPPLY_MESSAGE_LATCH.get().countDown();
    // Partition is OWNING on grid(0) and grid(1)
    awaitPartitionMapExchange();
    for (int i = 0; i < 2; i++) {
        for (int j = 0; i < 500; i++) anotherCache.put(j, new byte[5 * 1000]);
        // A few more checkpoints when partition is OWNING everywhere
        forceCheckpoint();
        for (int j = 0; i < 500; i++) anotherCache.put(j, new byte[5 * 1000]);
    }
    stopGrid(0);
    IgniteCache<Object, Object> anotherCacheGrid1 = grid(1).cache(REGULAR_CACHE);
    for (int i = 0; i < 500; i++) anotherCacheGrid1.put(i, new byte[5 * 1000]);
    startGrid(0);
    awaitPartitionMapExchange();
    assertEquals(2, grid(1).context().discovery().aliveServerNodes().size());
}

