/**
 * @throws Exception If failed.
 */
@Test
public void testConcurrentGrowDegenerateTreeAndConcurrentRemove() throws Exception {
    //calculate tree size when split happens
    final TestTree t = createTestTree(true);
    long i = 0;
    for (; ; i++) {
        t.put(i);
        if (//split happened
        t.rootLevel() > 0)
            break;
    }
    final long treeStartSize = i;
    final AtomicReference<Throwable> failed = new AtomicReference<>();
    for (int k = 0; k < 100; k++) {
        final TestTree tree = createTestTree(true);
        final AtomicBoolean start = new AtomicBoolean();
        final AtomicInteger ready = new AtomicInteger();
        Thread first = new Thread(new Runnable() {

            @Override
            public void run() {
                ready.incrementAndGet();
                //waiting without blocking
                while (!start.get()) ;
                try {
                    tree.remove(treeStartSize / 2L);
                } catch (Throwable th) {
                    failed.set(th);
                }
            }
        });
        Thread second = new Thread(new Runnable() {

            @Override
            public void run() {
                ready.incrementAndGet();
                //waiting without blocking
                while (!start.get()) ;
                try {
                    tree.put(treeStartSize + 1);
                } catch (Throwable th) {
                    failed.set(th);
                }
            }
        });
        for (int j = 0; j < treeStartSize; j++) tree.put((long) j);
        first.start();
        second.start();
        while (ready.get() != 2) ;
        start.set(true);
        first.join();
        second.join();
        assertNull(failed.get());
    }
}

