        assertEquals(cnt, cache.query(new SqlFieldsQuery("select null from dbvalue")).getAll().size());
        int limit = 500;
        List<List<?>> res = cache.query(new SqlFieldsQuery("select ival, _val from dbvalue where ival < ? order by ival").setArgs(limit)).getAll();
        assertEquals(limit, res.size());
        for (int i = 0; i < limit; i++) {
            List<?> row = res.get(i);
            assertEquals(2, row.size());
            assertEquals(i, row.get(0));
            assertEquals(new DbValue(i, "test-value", i), row.get(1));
        }
        assertEquals(1, cache.query(new SqlFieldsQuery("select lval from dbvalue where ival = 7899")).getAll().size());
        assertEquals(2000, cache.query(new SqlFieldsQuery("select lval from dbvalue where ival >= 5000 and ival < 7000")).getAll().size());
        String plan = cache.query(new SqlFieldsQuery("explain select lval from dbvalue where ival >= 5000 and ival < 7000")).getAll().get(0).get(0).toString();
        assertTrue(plan, plan.contains("IVAL_IDX"));
    }
}

