    IgfsEntryInfo z = mkdirsAndGetInfo("/a/k");
    // Files:
    IgfsEntryInfo f1 = createFileAndGetInfo("/f1");
    IgfsEntryInfo f2 = createFileAndGetInfo("/a/f2");
    IgfsEntryInfo f3 = createFileAndGetInfo("/a/b/f3");
