            while (!stop.get()) {
                stopGrid(gridIdx, true);
                Thread.sleep(50L);
                startGrid(gridIdx);
                Thread.sleep(50L);
            }
        } catch (Exception e) {
            log.error(e.getMessage(), e);
        }
    }, cnt - 1);
    long start = System.currentTimeMillis();
    long duration = GridTestUtils.SF.applyLB(15_000, 5_000);
    try {
        while (System.currentTimeMillis() < start + duration) {
            ThreadLocalRandom rnd = ThreadLocalRandom.current();
            metastorage(0).write("key" + rnd.nextInt(5000), Integer.toString(rnd.nextInt(1000)));
        }
    } finally {
        stop.set(true);
        fut.get();
    }
    awaitPartitionMapExchange();
    for (int i = 1; i < cnt; i++) assertDistributedMetastoragesAreEqual(grid(0), grid(i));
}

