        nextVal--;
    }
    assert nextVal == -1 : "Unexpected value: " + nextVal;
    // Test keys as enumeration.
    nextVal = 99;
    for (Enumeration<Integer> e = tst.descendingElements(); e.hasMoreElements(); ) {
        int i = e.nextElement();
        assert nextVal == i : "Unexpected value: " + i;
        nextVal--;
    }
    assert nextVal == -1 : "Unexpected value: " + nextVal;
