                            int idx = rnd.nextInt(numPairs);
                            int delta = rnd.nextInt(100_000);
                            data[idx].a += delta;
                            data[idx].b -= delta;
                        } finally {
                            lock.writeUnlock(ptr, TAG_0);
                        }
