/**
 */
@SuppressWarnings({ "ThrowableNotThrown" })
@Test
public void testPermissionBuilder() {
    SecurityBasicPermissionSet exp = new SecurityBasicPermissionSet();
    Map<String, Collection<SecurityPermission>> permCache = new HashMap<>();
    permCache.put("cache1", permissions(CACHE_PUT, CACHE_REMOVE));
    permCache.put("cache2", permissions(CACHE_READ));
    exp.setCachePermissions(permCache);
    Map<String, Collection<SecurityPermission>> permTask = new HashMap<>();
    permTask.put("task1", permissions(TASK_CANCEL));
    permTask.put("task2", permissions(TASK_EXECUTE));
    exp.setTaskPermissions(permTask);
    Map<String, Collection<SecurityPermission>> permSrvc = new HashMap<>();
    permSrvc.put("service1", permissions(SERVICE_DEPLOY));
    permSrvc.put("service2", permissions(SERVICE_INVOKE));
    exp.setServicePermissions(permSrvc);
    exp.setSystemPermissions(permissions(ADMIN_VIEW, EVENTS_ENABLE, JOIN_AS_SERVER, CACHE_CREATE, CACHE_DESTROY));
    final SecurityPermissionSetBuilder permsBuilder = new SecurityPermissionSetBuilder();
    assertThrows(log, new Callable<Object>() {

        @Override
        public Object call() throws Exception {
            permsBuilder.appendCachePermissions("cache", ADMIN_VIEW);
            return null;
        }
    }, IgniteException.class, "you can assign permission only start with [CACHE_], but you try ADMIN_VIEW");
    assertThrows(log, new Callable<Object>() {

        @Override
        public Object call() throws Exception {
            permsBuilder.appendTaskPermissions("task", CACHE_READ, JOIN_AS_SERVER);
            return null;
        }
    }, IgniteException.class, "you can assign permission only start with [TASK_], but you try CACHE_READ");
    assertThrows(log, new Callable<Object>() {

        @Override
        public Object call() throws Exception {
            permsBuilder.appendSystemPermissions(TASK_EXECUTE, CACHE_PUT);
            return null;
        }
    }, IgniteException.class, "you can assign permission only start with [EVENTS_, ADMIN_, CACHE_CREATE, CACHE_DESTROY, JOIN_AS_SERVER], but you try TASK_EXECUTE");
    assertThrows(log, new Callable<Object>() {

        @Override
        public Object call() throws Exception {
            permsBuilder.appendSystemPermissions(SERVICE_INVOKE, CACHE_REMOVE);
            return null;
        }
    }, IgniteException.class, "you can assign permission only start with [EVENTS_, ADMIN_, CACHE_CREATE, CACHE_DESTROY, JOIN_AS_SERVER], but you try SERVICE_INVOKE");
    assertThrows(log, new Callable<Object>() {

        @Override
        public Object call() throws Exception {
            permsBuilder.appendCachePermissions("cache", CACHE_CREATE);
            return null;
        }
    }, IgniteException.class, "CACHE_CREATE should be assigned as system permission, not cache permission");
    permsBuilder.appendCachePermissions("cache1", CACHE_PUT).appendCachePermissions("cache1", CACHE_PUT, CACHE_REMOVE).appendCachePermissions("cache2", CACHE_READ).appendTaskPermissions("task1", TASK_CANCEL).appendTaskPermissions("task2", TASK_EXECUTE).appendTaskPermissions("task2", TASK_EXECUTE).appendServicePermissions("service1", SERVICE_DEPLOY).appendServicePermissions("service2", SERVICE_INVOKE).appendServicePermissions("service2", SERVICE_INVOKE).appendSystemPermissions(ADMIN_VIEW).appendSystemPermissions(ADMIN_VIEW, EVENTS_ENABLE).appendSystemPermissions(JOIN_AS_SERVER).appendSystemPermissions(CACHE_CREATE, CACHE_DESTROY);
    SecurityPermissionSet actual = permsBuilder.build();
    assertEquals(exp.cachePermissions(), actual.cachePermissions());
    assertEquals(exp.taskPermissions(), actual.taskPermissions());
    assertEquals(exp.servicePermissions(), actual.servicePermissions());
    assertEquals(exp.systemPermissions(), actual.systemPermissions());
    assertEquals(exp.defaultAllowAll(), actual.defaultAllowAll());
}

