                    Deque<GridTestMessage> queue = msgs.get(to.id());
                    if (queue == null) {
                        Deque<GridTestMessage> old = msgs.putIfAbsent(to.id(), queue = new ConcurrentLinkedDeque<>());
                        if (old != null)
                            queue = old;
                    }
                    queue.offer(msg);
                }
            } catch (IgniteException e) {
                log().error("Unable to send message.", e);
