            return true;
        }
    }, EVT_CLIENT_NODE_DISCONNECTED, EVT_CLIENT_NODE_RECONNECTED);
    srv.close();
    assertTrue(disconnectLatch.await(30, SECONDS));
    discoPort.set(TcpDiscoverySpi.DFLT_PORT + 100);
