@Test
public void testTransactionInfo() throws Exception {
    client.getOrCreateCache(new CacheConfiguration<>(DEFAULT_CACHE_NAME).setAtomicityMode(TRANSACTIONAL).setBackups(1).setWriteSynchronizationMode(FULL_SYNC));
    for (Ignite ig : G.allGrids()) assertNotNull(ig.cache(DEFAULT_CACHE_NAME));
    CountDownLatch lockLatch = new CountDownLatch(1);
    CountDownLatch unlockLatch = new CountDownLatch(1);
    IgniteInternalFuture<?> fut = startTransactions("testTransactionInfo", lockLatch, unlockLatch, false);
    try {
        U.awaitQuiet(lockLatch);
        // Should be more than enough for all transactions to appear in contexts.
        doSleep(3000);
        Set<GridCacheVersion> nearXids = new HashSet<>();
        for (int i = 0; i < SERVER_NODE_CNT; i++) {
            IgniteEx grid = grid(i);
            IgniteTxManager tm = grid.context().cache().context().tm();
            for (IgniteInternalTx tx : tm.activeTransactions()) nearXids.add(tx.nearXidVersion());
        }
        injectTestSystemOut();
        for (GridCacheVersion nearXid : nearXids) {
            assertEquals(EXIT_CODE_OK, execute("--tx", "--info", nearXid.toString()));
