        } catch (Exception e) {
            fail();
        }
    }, 1, "start-node-thread");
    // Give enough time to reach exchange future.
    doSleep(5000);
    assertEquals(EXIT_CODE_OK, execute(h, "--tx"));
    // Test kill by xid.
