    List<List<?>> srvNodeIndexes = execSql(srv, idxSql);
    List<List<?>> clientNodeNodeIndexes = execSql(client, idxSql);
    for (List<?> idx : clientNodeNodeIndexes) assertTrue(srvNodeIndexes.contains(idx));
    String[][] expectedResults = { { "-825022849", "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "IDX_GEO_1", "SPATIAL", "\"GEOM\" ASC", "false", "false", "0" }, { "-825022849", "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "_key_PK", "BTREE", "\"ID1\" ASC", "true", "true", "5" }, { "-825022849", "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "_key_PK__SCAN_", "SCAN", "null", "false", "false", "0" }, { "-825022849", "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "_key_PK_hash", "HASH", "\"ID1\" ASC", "true", "true", "0" }, { "-825022849", "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "_key_PK_proxy", "BTREE", "\"ID1\" ASC", "false", "false", "0" } };
    for (int i = 0; i < srvNodeIndexes.size(); i++) {
        List<?> resRow = srvNodeIndexes.get(i);
