    fs.close();
    // "Not set" => true transition.
    igfs.globalSampling(true);
    fs = fileSystem();
    assert logEnabled();
    fs.close();
    // True => "not set" transition.
    igfs.globalSampling(null);
    fs = fileSystem();
    assert !logEnabled();
    // "Not-set" => false transition.
    igfs.globalSampling(false);
    fs = fileSystem();
    assert !logEnabled();
    fs.close();
    // False => "not=set" transition.
    igfs.globalSampling(null);
    fs = fileSystem();
    assert !logEnabled();
    fs.close();
    // True => false transition.
    igfs.globalSampling(true);
    igfs.globalSampling(false);
    fs = fileSystem();
    assert !logEnabled();
    fs.close();
    // False => true transition.
    igfs.globalSampling(true);
    fs = fileSystem();
    assert logEnabled();
}

