        public void applyx() throws IgniteCheckedException {
            GridRandom rnd = new GridRandom();
            while (!qrysDone.get()) {
                SqlFieldsQuery qry = new SqlFieldsQuery(QRY);
                boolean smallPageSize = rnd.nextBoolean();
                if (smallPageSize)
                    qry.setPageSize(3);
                List<List<?>> res;
                try {
                    res = clientCache.query(qry).getAll();
                } catch (CacheException e) {
                    assertTrue("On large page size must retry.", smallPageSize);
                    boolean failedOnRemoteFetch = false;
                    for (Throwable th = e; th != null; th = th.getCause()) {
                        if (!(th instanceof CacheException))
                            continue;
                        if (th.getMessage() != null && th.getMessage().startsWith("Failed to fetch data from node:")) {
                            failedOnRemoteFetch = true;
                            break;
                        }
                    }
                    if (!failedOnRemoteFetch) {
                        e.printStackTrace();
                        fail("Must fail inside of GridResultPage.fetchNextPage or subclass.");
                    }
                    res = FAKE;
                }
                if (res != FAKE && !res.equals(pRes)) {
                    int j = 0;
                    // Check for data loss.
                    for (String cacheName : F.asList("co", "pr", "pe", "pu")) {
                        assertEquals(cacheName, cacheSize.get(j++).intValue(), grid(GRID_CNT - 1).cache(cacheName).size());
                    }
                    // Fail with nice message.
                    assertEquals(pRes, res);
                }
                int c = qryCnt.incrementAndGet();
                if (c % logFreq == 0)
                    info("Executed queries: " + c);
            }
        }
    }, qryThreadNum, "query-thread");
    final AtomicInteger restartCnt = new AtomicInteger();
    final AtomicBoolean restartsDone = new AtomicBoolean();
    IgniteInternalFuture<?> fut2 = multithreadedAsync(new Callable<Object>() {

        @SuppressWarnings({ "BusyWait" })
        @Override
        public Object call() throws Exception {
            GridRandom rnd = new GridRandom();
            while (!restartsDone.get()) {
                int g;
                do {
                    g = rnd.nextInt(locks.length());
                } while (!locks.compareAndSet(g, 0, -1));
                log.info("Stop node: " + g);
                stopGrid(g);
                Thread.sleep(rnd.nextInt(nodeLifeTime));
                log.info("Start node: " + g);
                startGrid(g);
                Thread.sleep(rnd.nextInt(nodeLifeTime));
                locks.set(g, 0);
                int c = restartCnt.incrementAndGet();
                if (c % logFreq == 0)
                    info("Node restarts: " + c);
            }
            return true;
        }
    }, restartThreadsNum, "restart-thread");
    Thread.sleep(duration);
    info("Stopping..");
    restartsDone.set(true);
    fut2.get();
    info("Restarts stopped.");
    qrysDone.set(true);
    fut1.get();
    info("Queries stopped.");
}

/**
 * Tests partition validation.
 */
@Test
public void testPartitions() {
    final SqlFieldsQuery qry = new SqlFieldsQuery("select 1");
    // Empty set is not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions();
        }
    });
    // Duplicates are not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions(0, 1, 2, 1);
        }
    });
    // Values out of range are not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions(-1, 0, 1);
        }
    });
    // Duplicates with unordered input are not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions(3, 2, 2);
        }
    });
    // Values out of range are not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions(-1, 0, 1);
        }
    });
    // Expecting ordered set.
    int[] tmp = new int[] { 6, 2, 3 };
    qry.setPartitions(tmp);
    assertTrue(Arrays.equals(new int[] { 2, 3, 6 }, tmp));
    // If already ordered expecting same instance.
    qry.setPartitions((tmp = new int[] { 0, 1, 2 }));
    assertTrue(tmp == qry.getPartitions());
}

