@Test
public void testManyTables() {
    Ignite ignite = ignite(0);
    queryProcessor(ignite).querySqlFields(new SqlFieldsQuery("CREATE TABLE Person(ID INTEGER PRIMARY KEY, NAME VARCHAR(100))"), true);
    queryProcessor(ignite).querySqlFields(new SqlFieldsQuery("INSERT INTO Person(ID, NAME) VALUES (1, 'Ed'), (2, 'Ann'), (3, 'Emma')"), true);
    SqlFieldsQuery selectQuery = new SqlFieldsQuery("SELECT P1.NAME " + "FROM PERSON P1 " + "JOIN PERSON P2 ON P1.ID = P2.ID " + "JOIN PERSON P3 ON P1.ID = P3.ID " + "JOIN PERSON P4 ON P1.ID = P4.ID " + "JOIN PERSON P5 ON P1.ID = P5.ID " + "JOIN PERSON P6 ON P1.ID = P6.ID " + "JOIN PERSON P7 ON P1.ID = P7.ID " + "JOIN PERSON P8 ON P1.ID = P8.ID " + "ORDER BY P1.NAME").setDistributedJoins(true).setEnforceJoinOrder(false);
    List<List<?>> res = queryProcessor(ignite).querySqlFields(selectQuery, true).getAll();
    assertEquals(3, res.size());
    assertThat(res.get(0).get(0), is("Ann"));
    assertThat(res.get(1).get(0), is("Ed"));
