@Test
public void testComputeBroadcast() throws Exception {
    CyclicBarrier barrier = new CyclicBarrier(6);
    for (int i = 0; i < 5; i++) {
        ignite0.compute().broadcastAsync(() -> {
            try {
                barrier.await();
                barrier.await();
            } catch (InterruptedException | BrokenBarrierException e) {
                throw new RuntimeException(e);
            }
        });
    }
    barrier.await();
    List<List<?>> tasks = execute(ignite0, "SELECT " + "  INTERNAL, " + "  AFFINITY_CACHE_NAME, " + "  AFFINITY_PARTITION_ID, " + "  TASK_CLASS_NAME, " + "  TASK_NAME, " + "  TASK_NODE_ID, " + "  USER_VERSION " + "FROM SYS.TASKS");
    assertEquals(5, tasks.size());
    List<?> t = tasks.get(0);
    assertFalse((Boolean) t.get(0));
    assertNull(t.get(1));
    assertEquals(-1, t.get(2));
    assertTrue(t.get(3).toString().startsWith(getClass().getName()));
    assertTrue(t.get(4).toString().startsWith(getClass().getName()));
    assertEquals(ignite0.localNode().id(), t.get(5));
    assertEquals("0", t.get(6));
    barrier.await();
}

