@Test
public void testDistributedJoinSimple() throws Exception {
    startGridsMultiThreaded(4);
    Ignite srv0 = ignite(0);
    int[] backups = { 0, 1, 2 };
    for (int b : backups) {
        IgniteCache<Object, Object> cache = srv0.createCache(cacheConfiguration(cacheMode(), FULL_SYNC, b, DFLT_PARTITION_COUNT).setIndexedTypes(JoinTestParentKey.class, JoinTestParent.class, JoinTestChildKey.class, JoinTestChild.class));
        int cntr = 0;
        int expCnt = 0;
        for (int i = 0; i < 10; i++) {
            JoinTestParentKey parentKey = new JoinTestParentKey(i);
            cache.put(parentKey, new JoinTestParent(i));
            for (int c = 0; c < i; c++) {
                JoinTestChildKey childKey = new JoinTestChildKey(cntr++);
                cache.put(childKey, new JoinTestChild(i));
                expCnt++;
            }
        }
        SqlFieldsQuery qry = new SqlFieldsQuery("select c.parentId, p.id from " + "JoinTestChild c join JoinTestParent p on (c.parentId = p.id)").setDistributedJoins(true);
        Map<Integer, Integer> resMap = new HashMap<>();
        List<List<?>> res = cache.query(qry).getAll();
        assertEquals(expCnt, res.size());
        for (List<?> resRow : res) {
            Integer parentId = (Integer) resRow.get(0);
            Integer cnt = resMap.get(parentId);
            if (cnt == null)
                resMap.put(parentId, 1);
            else
                resMap.put(parentId, cnt + 1);
        }
        for (int i = 1; i < 10; i++) assertEquals(i, (Object) resMap.get(i));
        srv0.destroyCache(cache.getName());
    }
}

