/**
 * @throws Exception If failed.
 */
@Test
public void testQueryDeadlockImplicit() throws Exception {
    ccfg = cacheConfiguration(cacheMode(), FULL_SYNC, 0, DFLT_PARTITION_COUNT).setIndexedTypes(Integer.class, Integer.class);
    startGridsMultiThreaded(2);
    final Phaser phaser = new Phaser(2);
    final AtomicReference<Exception> ex = new AtomicReference<>();
    GridTestUtils.runAsync(new Runnable() {

        @Override
        public void run() {
            IgniteEx node = grid(0);
            try {
                try (Transaction tx = node.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
                    IgniteCache<Object, Object> cache0 = node.cache(DEFAULT_CACHE_NAME);
                    SqlFieldsQuery qry = new SqlFieldsQuery("INSERT INTO Integer (_key, _val) values (1,1),(2,2),(3,3)");
                    try (FieldsQueryCursor<List<?>> cur = cache0.query(qry)) {
                        cur.getAll();
                    }
                    awaitPhase(phaser, 2);
                    tx.commit();
                }
            } catch (Exception e) {
                onException(ex, e);
            } finally {
                phaser.arrive();
            }
        }
    });
    phaser.arriveAndAwaitAdvance();
    IgniteEx node = grid(1);
    IgniteCache<Object, Object> cache0 = node.cache(DEFAULT_CACHE_NAME);
    SqlFieldsQuery qry = new SqlFieldsQuery("INSERT INTO Integer (_key, _val) values (1,1),(2,2),(3,3)").setTimeout(TX_TIMEOUT, TimeUnit.MILLISECONDS);
    try (FieldsQueryCursor<List<?>> cur = cache0.query(qry)) {
        cur.getAll();
    } catch (Exception e) {
        phaser.arrive();
        onException(ex, e);
    }
    phaser.arriveAndAwaitAdvance();
    Exception ex0 = ex.get();
    assertNotNull(ex0);
    if (!X.hasCause(ex0, IgniteTxTimeoutCheckedException.class))
        throw ex0;
}

