/**
 * We start several nodes, populate caches, then start replacing values.
 * After that one node is killed, their index.bin files would be removed.
 * Finally, we restart the node, index rebuild starting after recovery.
 * And we checke indexes by "validate indexes" task.
 */
@Test
public void test() throws Exception {
    long start = System.currentTimeMillis();
    IgniteEx grid1 = startGrids(4);
    grid1.cluster().active(true);
    final int accountCount = 2048;
    try (IgniteDataStreamer streamer = grid1.dataStreamer(FIRST_CACHE)) {
        for (long i = 0; i < accountCount; i++) {
            streamer.addData(i, new Account(i));
        }
        streamer.flush();
    }
    try (IgniteDataStreamer streamer = grid1.dataStreamer(SECOND_CACHE)) {
        for (long i = 0; i < accountCount; i++) {
            streamer.addData(i, new Account(i));
        }
        streamer.flush();
    }
    AtomicBoolean stop = new AtomicBoolean();
    IgniteCache<Object, Object> cache1 = grid1.cache(FIRST_CACHE);
    IgniteCache<Object, Object> cache2 = grid1.cache(SECOND_CACHE);
    new Thread(new Runnable() {

        @Override
        public void run() {
            long i = 0;
            while (!stop.get()) {
                try {
                    cache1.put(i, new Account(i));
                    cache2.put(i, new Account(i));
                    i++;
                } catch (Throwable e) {
                    e.printStackTrace();
                }
            }
        }
    }).start();
    File workDirectory = U.resolveWorkDirectory(U.defaultWorkDirectory(), DFLT_STORE_DIR, false);
    long diff = System.currentTimeMillis() - start;
    U.sleep(7500 - (diff % 5000));
    IgniteProcessProxy.kill(getTestIgniteInstanceName(3));
    stop.set(true);
    for (File grp : new File(workDirectory, U.maskForFileName(getTestIgniteInstanceName(3))).listFiles()) {
        new File(grp, "index.bin").delete();
    }
    startGrid(3);
    awaitPartitionMapExchange();
    U.sleep(3_000);
    ImmutableSet<UUID> nodes = ImmutableSet.of(((IgniteProcessProxy) grid(3)).getId(), ((IgniteProcessProxy) grid(2)).getId());
    VisorValidateIndexesTaskArg arg = new VisorValidateIndexesTaskArg(null, null, 10000, 1);
    VisorTaskArgument<VisorValidateIndexesTaskArg> argument = new VisorTaskArgument<>(nodes, arg, true);
    ComputeTaskInternalFuture<VisorValidateIndexesTaskResult> execute = grid1.context().task().execute(new VisorValidateIndexesTask(), argument);
    VisorValidateIndexesTaskResult result = execute.get();
    Map<UUID, VisorValidateIndexesJobResult> results = result.results();
    boolean hasIssue = false;
    for (VisorValidateIndexesJobResult jobResult : results.values()) {
        System.err.println(jobResult);
        hasIssue |= jobResult.hasIssues();
    }
    assertFalse(hasIssue);
}

/**
 * Do test.
 * <p>
 * Steps are as follows:
 * <ul>
 *     <li>Put some data;</li>
 *     <li>Stop the node;</li>
 *     <li>Remove index file;</li>
 *     <li>Restart the node and block index rebuild;</li>
 *     <li>For half of the keys do cache puts <b>before</b> corresponding key
 *     has been processed during index rebuild;</li>
 *     <li>Check that:
 *         <ul>
 *             <li>For MVCC case: some keys have all versions that existed before restart, while those
 *             updated concurrently have only put version (one with mark value -1)
 *             and latest version present before node restart;</li>
 *             <li>For non MVCC case: keys updated concurrently must have mark values of -1 despite that
 *             index rebuild for them has happened after put.</li>
 *         </ul>
 *     </li>
 * </ul></p>
 * @throws Exception if failed.
 */
@Test
public void testIndexRebuild() throws Exception {
    IgniteEx srv = startServer();
    execute(srv, "CREATE TABLE T(k int primary key, v int) WITH \"cache_name=T,wrap_value=false," + "atomicity=transactional\"");
    execute(srv, "CREATE INDEX IDX ON T(v)");
    IgniteInternalCache cc = srv.cachex(CACHE_NAME);
    assertNotNull(cc);
    putData(srv, false);
    checkDataState(srv, false);
    File cacheWorkDir = ((FilePageStoreManager) cc.context().shared().pageStore()).cacheWorkDir(cc.configuration());
    File idxPath = cacheWorkDir.toPath().resolve("index.bin").toFile();
    stopAllGrids();
    assertTrue(U.delete(idxPath));
    srv = startServer();
    putData(srv, true);
    checkDataState(srv, true);
}

