/**
 * Test how partition ownership is transferred in various cases.
 */
@Test
public void testPartitionTransfer() {
    // First co-located table.
    createPartitionedTable("t1", pkColumn("k1"), "v2");
    // Second co-located table.
    createPartitionedTable("t2", pkColumn("k1"), affinityColumn("ak2"), "v3");
    // Third co-located table.
    createPartitionedTable("t3", pkColumn("k1"), affinityColumn("ak2"), "v3", "v4");
    // Transfer through "AND".
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 = ? AND t2.ak2 = ?", (res) -> assertPartitions(partition("t1", "1")), "1", "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 = ? AND t2.ak2 = ?", (res) -> assertNoRequests(), "1", "2");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 = ? AND t2.ak2 IN (?, ?)", (res) -> assertPartitions(partition("t1", "1")), "1", "1", "2");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 = ? AND t2.ak2 IN (?, ?)", (res) -> assertNoRequests(), "1", "2", "3");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 IN (?, ?) AND t2.ak2 IN (?, ?)", (res) -> assertPartitions(partition("t1", "2")), "1", "2", "2", "3");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 IN (?, ?) AND t2.ak2 IN (?, ?)", (res) -> assertNoRequests(), "1", "2", "3", "4");
    // Transfer through "OR".
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 = ? OR t2.ak2 = ?", (res) -> assertPartitions(partition("t1", "1")), "1", "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 = ? OR t2.ak2 = ?", (res) -> assertPartitions(partition("t1", "1"), partition("t2", "2")), "1", "2");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 = ? OR t2.ak2 IN (?, ?)", (res) -> assertPartitions(partition("t1", "1"), partition("t2", "2")), "1", "1", "2");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 = ? OR t2.ak2 IN (?, ?)", (res) -> assertPartitions(partition("t1", "1"), partition("t2", "2"), partition("t2", "3")), "1", "2", "3");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 IN (?, ?) OR t2.ak2 IN (?, ?)", (res) -> assertPartitions(partition("t1", "1"), partition("t1", "2"), partition("t2", "3")), "1", "2", "2", "3");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 WHERE t1.k1 IN (?, ?) OR t2.ak2 IN (?, ?)", (res) -> assertPartitions(partition("t1", "1"), partition("t1", "2"), partition("t2", "3"), partition("t2", "4")), "1", "2", "3", "4");
    // Multi-way co-located JOIN.
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 INNER JOIN t3 ON t1.k1 = t3.ak2 " + "WHERE t1.k1 = ? AND t2.ak2 = ? AND t3.ak2 = ?", (res) -> assertPartitions(partition("t1", "1")), "1", "1", "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 = t2.ak2 INNER JOIN t3 ON t1.k1 = t3.ak2 " + "WHERE t1.k1 = ? AND t2.ak2 = ? AND t3.ak2 = ?", (res) -> assertNoRequests(), "1", "2", "3");
    // No transfer through intermediate table.
    execute("SELECT * FROM t1 INNER JOIN t3 ON t1.k1 = t3.v3 INNER JOIN t2 ON t3.v4 = t2.ak2 " + "WHERE t1.k1 = ? AND t2.ak2 = ?", (res) -> assertNoPartitions(), "1", "1");
    // No transfer through disjunction.
    execute("SELECT * FROM t1 INNER JOIN t2 ON 1=1 WHERE t1.k1 = ? OR t1.k1 = t2.ak2", (res) -> assertNoPartitions(), "1");
}

/**
 * Test cross-joins. They cannot "transfer" partitions between joined tables.
 */
@Test
public void testCrossJoin() {
    createPartitionedTable("t1", pkColumn("k1"), "v2");
    createPartitionedTable("t2", pkColumn("k1"), affinityColumn("ak2"), "v3");
    executeSql("INSERT INTO t1 VALUES ('1', '1')");
    executeSql("INSERT INTO t2 VALUES ('1', '1', '1')");
    executeSql("INSERT INTO t1 VALUES ('2', '2')");
    executeSql("INSERT INTO t2 VALUES ('2', '2', '2')");
    executeSql("INSERT INTO t1 VALUES ('3', '3')");
    executeSql("INSERT INTO t2 VALUES ('3', '3', '3')");
    // Left table, should work.
    execute("SELECT * FROM t1, t2 WHERE t1.k1 = ?", (res) -> {
        assertPartitions(partition("t1", "1"));
        assertEquals(1, res.size());
        assertEquals("1", res.get(0).get(0));
    }, "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON 1=1 WHERE t1.k1 = ?", (res) -> {
        assertPartitions(partition("t1", "1"));
        assertEquals(1, res.size());
        assertEquals("1", res.get(0).get(0));
    }, "1");
    // Right table, should work.
    execute("SELECT * FROM t1, t2 WHERE t2.ak2 = ?", (res) -> {
        assertPartitions(partition("t2", "2"));
        assertEquals(1, res.size());
        assertEquals("2", res.get(0).get(0));
    }, "2");
    execute("SELECT * FROM t1 INNER JOIN t2 ON 1=1 WHERE t2.ak2 = ?", (res) -> {
        assertPartitions(partition("t2", "2"));
        assertEquals(1, res.size());
        assertEquals("2", res.get(0).get(0));
    }, "2");
    execute("SELECT * FROM t1, t2 WHERE t1.k1=? AND t2.ak2 = ?", (res) -> assertNoPartitions(), "3", "3");
    // Two tables, should not work.
    execute("SELECT * FROM t1, t2 WHERE t1.k1=? AND t2.ak2 = ?", (res) -> assertNoPartitions(), "3", "3");
    execute("SELECT * FROM t1 INNER JOIN t2 ON 1=1 WHERE t1.k1=? AND t2.ak2 = ?", (res) -> assertNoPartitions(), "3", "3");
}

/**
 * Test non-equijoins.
 */
@Test
public void testThetaJoin() {
    createPartitionedTable("t1", pkColumn("k1"), "v2");
    createPartitionedTable("t2", pkColumn("k1"), affinityColumn("ak2"), "v3");
    // Greater than.
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 > t2.ak2 WHERE t1.k1 = ?", (res) -> assertPartitions(partition("t1", "1")), "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 > t2.ak2 WHERE t2.ak2 = ?", (res) -> assertPartitions(partition("t1", "1")), "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 > t2.ak2 WHERE t1.k1 = ? AND t2.ak2 = ?", (res) -> assertNoPartitions(), "1", "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 > t2.ak2 WHERE t1.k1 = ? OR t2.ak2 = ?", (res) -> assertNoPartitions(), "1", "2");
    // Less than.
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 < t2.ak2 WHERE t1.k1 = ?", (res) -> assertPartitions(partition("t1", "1")), "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 < t2.ak2 WHERE t2.ak2 = ?", (res) -> assertPartitions(partition("t1", "1")), "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 < t2.ak2 WHERE t1.k1 = ? AND t2.ak2 = ?", (res) -> assertNoPartitions(), "1", "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 < t2.ak2 WHERE t1.k1 = ? OR t2.ak2 = ?", (res) -> assertNoPartitions(), "1", "2");
    // Non-equal.
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 <> t2.ak2 WHERE t1.k1 = ?", (res) -> assertPartitions(partition("t1", "1")), "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 <> t2.ak2 WHERE t2.ak2 = ?", (res) -> assertPartitions(partition("t1", "1")), "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 <> t2.ak2 WHERE t1.k1 = ? AND t2.ak2 = ?", (res) -> assertNoPartitions(), "1", "1");
    execute("SELECT * FROM t1 INNER JOIN t2 ON t1.k1 <> t2.ak2 WHERE t1.k1 = ? OR t2.ak2 = ?", (res) -> assertNoPartitions(), "1", "2");
}

