    execute("DELETE FROM t1 WHERE k1 in (?, ?) or k1 = ?", (res) -> {
        assertPartitions(partition("t1", "1"), partition("t1", "2"), partition("t1", "3"));
        assertNodes(node("t1", "1"), node("t1", "2"), node("t1", "3"));
        assertUpdatedRows(res, 3);
    }, "3", "2", "1");
    // No request (empty partitions).
    execute("DELETE FROM t1  WHERE k1 in (?, ?) and k1 = ?", (res) -> {
        assertNoRequests();
        assertUpdatedRows(res, 0);
    }, "3", "2", "1");
}

