@Test
public void testPushDown() {
    IgniteCache<Integer, Person> c = ignite(CLIENT).getOrCreateCache(cacheConfig("ps", true, Integer.class, Person.class));
    try {
        String subqry = "(select max(p.id) as id, p.depId from Person p group by p.depId)";
        for (int i = 0; i < 5; i++) {
            SB qry = new SB("select * from ");
            for (int j = 0; j < 5; j++) {
                if (j != 0)
                    qry.a(", ");
                if (j == i)
                    qry.a(subqry);
                else
                    qry.a("Person");
                qry.a(" p").a(j);
            }
            qry.a(" where");
            for (int j = 1; j < 5; j++) {
                if (j != 1)
                    qry.a(" and");
                qry.a(" p").a(j - 1).a(".id").a(" = ").a("p").a(j).a(".depId");
            }
            c.query(new SqlFieldsQuery(qry.toString()).setEnforceJoinOrder(true)).getAll();
            X.println("\nPlan:\n" + c.query(new SqlFieldsQuery("explain " + qry.toString()).setEnforceJoinOrder(true)).getAll());
        }
    } finally {
