 * @throws Exception Exception in case of failure.
 */
@Test
public void testCloseRunningQueriesOnNodeStop() throws Exception {
    IgniteEx ign = startGrid(super.getConfiguration("TST"));
    IgniteCache<Integer, Integer> cache = ign.getOrCreateCache(new CacheConfiguration<Integer, Integer>().setName("TST").setQueryEntities(Collections.singletonList(new QueryEntity(Integer.class, Integer.class))));
    for (int i = 0; i < 10000; i++) cache.put(i, i);
