    assertEquals(7L, execSql(ignite3, "SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHES WHERE CACHE_NAME like 'cache%'").get(0).get(0));
    // Check cache groups.
    resAll = execSql("SELECT CACHE_GROUP_ID, CACHE_GROUP_NAME, IS_SHARED, CACHE_COUNT, " + "CACHE_MODE, ATOMICITY_MODE, AFFINITY, PARTITIONS_COUNT, " + "NODE_FILTER, DATA_REGION_NAME, TOPOLOGY_VALIDATOR, PARTITION_LOSS_POLICY, " + "REBALANCE_MODE, REBALANCE_DELAY, REBALANCE_ORDER, BACKUPS " + "FROM " + systemSchemaName() + ".CACHE_GROUPS");
