    assertEquals(2, execSql("SELECT CACHE_COUNT FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE CACHE_GROUP_NAME = 'cache_grp'").get(0).get(0));
    assertEquals("cache_grp", execSql("SELECT CACHE_GROUP_NAME FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE IS_SHARED = true AND CACHE_GROUP_NAME like 'cache%'").get(0).get(0));
    // Check index on ID column.
    assertEquals("cache_tx_repl", execSql("SELECT CACHE_GROUP_NAME FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE CACHE_GROUP_ID = ?", ignite0.cachex("cache_tx_repl").context().groupId()).get(0).get(0));
    assertEquals(0, execSql("SELECT CACHE_GROUP_ID FROM " + systemSchemaName() + ".CACHE_GROUPS WHERE CACHE_GROUP_ID = 0").size());
    // Check join by indexed column.
    assertEquals("cache_tx_repl", execSql("SELECT CG.CACHE_GROUP_NAME FROM " + systemSchemaName() + ".CACHES C JOIN " + systemSchemaName() + ".CACHE_GROUPS CG ON C.CACHE_GROUP_ID = CG.CACHE_GROUP_ID WHERE C.CACHE_NAME = 'cache_tx_repl'").get(0).get(0));
    // Check join by non-indexed column.
    assertEquals("cache_grp", execSql("SELECT CG.CACHE_GROUP_NAME FROM " + systemSchemaName() + ".CACHES C JOIN " + systemSchemaName() + ".CACHE_GROUPS CG ON C.CACHE_GROUP_NAME = CG.CACHE_GROUP_NAME WHERE C.CACHE_NAME = 'cache_tx_part'").get(0).get(0));
    // Check configuration equality for cache and cache group views.
    assertEquals(5L, execSql("SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHES C JOIN " + systemSchemaName() + ".CACHE_GROUPS CG " + "ON C.CACHE_NAME = CG.CACHE_GROUP_NAME WHERE C.CACHE_NAME like 'cache%' " + "AND C.CACHE_MODE = CG.CACHE_MODE " + "AND C.ATOMICITY_MODE = CG.ATOMICITY_MODE " + "AND COALESCE(C.AFFINITY, '-') = COALESCE(CG.AFFINITY, '-') " + "AND COALESCE(C.NODE_FILTER, '-') = COALESCE(CG.NODE_FILTER, '-') " + "AND COALESCE(C.DATA_REGION_NAME, '-') = COALESCE(CG.DATA_REGION_NAME, '-') " + "AND COALESCE(C.TOPOLOGY_VALIDATOR, '-') = COALESCE(CG.TOPOLOGY_VALIDATOR, '-') " + "AND C.PARTITION_LOSS_POLICY = CG.PARTITION_LOSS_POLICY " + "AND C.REBALANCE_MODE = CG.REBALANCE_MODE " + "AND C.REBALANCE_DELAY = CG.REBALANCE_DELAY " + "AND C.REBALANCE_ORDER = CG.REBALANCE_ORDER " + "AND COALESCE(C.BACKUPS, -1) = COALESCE(CG.BACKUPS, -1)").get(0).get(0));
    // Check quick count.
    assertEquals(execSql("SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS").get(0).get(0), execSql("SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS WHERE CACHE_GROUP_ID <> CACHE_GROUP_ID + 1").get(0).get(0));
    // Check that cache groups are the same on different nodes.
    assertEquals(6L, execSql("SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE CACHE_GROUP_NAME like 'cache%'").get(0).get(0));
    assertEquals(6L, execSql(ignite1, "SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE CACHE_GROUP_NAME like 'cache%'").get(0).get(0));
    assertEquals(6L, execSql(ignite2, "SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE CACHE_GROUP_NAME like 'cache%'").get(0).get(0));
    assertEquals(6L, execSql(ignite3, "SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE CACHE_GROUP_NAME like 'cache%'").get(0).get(0));
    assertEquals(5L, execSql(ignite0, "SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE NODE_FILTER is NULL").get(0).get(0));
    assertEquals(1L, execSql(ignite0, "SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE NODE_FILTER = 'CUSTOM_NODE_FILTER'").get(0).get(0));
    assertEquals(1L, execSql(ignite0, "SELECT COUNT(*) FROM " + systemSchemaName() + ".CACHE_GROUPS " + "WHERE NODE_FILTER like '%Oops... incorrect customer realization.'").get(0).get(0));
}

/**
 * Regression test. Verifies that duration metrics is able to be longer than 24 hours.
 */
@Test
public void testDurationMetricsCanBeLonger24Hours() throws Exception {
    Ignite ign = startGrid("MockedMetrics", getConfiguration().setMetricsUpdateFrequency(500));
    ClusterNode node = ign.cluster().localNode();
    assert node instanceof TcpDiscoveryNode : "Setup failed, test is incorrect.";
    // Get rid of metrics provider: current logic ignores metrics field if provider != null.
    setField(node, "metricsProvider", null);
    ClusterMetricsImpl original = getField(node, "metrics");
    setField(node, "metrics", new MockedClusterMetrics(original));
    ;
    List<?> durationMetrics = execSql(ign, "SELECT " + "MAX_JOBS_WAIT_TIME, " + "CUR_JOBS_WAIT_TIME, " + "AVG_JOBS_WAIT_TIME, " + "MAX_JOBS_EXECUTE_TIME, " + "CUR_JOBS_EXECUTE_TIME, " + "AVG_JOBS_EXECUTE_TIME, " + "TOTAL_JOBS_EXECUTE_TIME, " + "TOTAL_BUSY_TIME, " + "TOTAL_IDLE_TIME, " + "CUR_IDLE_TIME, " + "UPTIME " + "FROM " + systemSchemaName() + ".NODE_METRICS").get(0);
    List<Long> elevenExpVals = LongStream.generate(() -> MockedClusterMetrics.LONG_DURATION_MS).limit(11).boxed().collect(Collectors.toList());
    assertEqualsCollections(elevenExpVals, durationMetrics);
}

