        stopGrid(1);
        ignite1 = startGrid(1);
        Integer res2 = (Integer) ignite1.compute().execute(task1, ignite2.cluster().localNode().id());
        assert !undeployed.await(3000, MILLISECONDS);
        assert res1.equals(res2);
    } finally {
